async function askNotify() {
  const ok = await showPrimer();   // 내 화면에서 이유 설명 + 예/아니오
  if (!ok) return;                 // 「아니오」면 OS 창 낭비 X (나중에 다시)
  const perm = await Notification.requestPermission();  // 「예」일 때만 OS 창
  if (perm === 'granted') await subscribe();
}
// 맥락에서 호출: 「재입고되면 알려 드릴까요?」 버튼 → askNotify()

// 클라이언트: 구독
const reg = await navigator.serviceWorker.ready;
const sub = await reg.pushManager.subscribe({
  userVisibleOnly: true,
  applicationServerKey: VAPID_PUBLIC_KEY,
});
await fetch('/subscribe', { method: 'POST', body: JSON.stringify(sub) });  // 서버에 저장

// 서비스 워커: 수신·표시·딥링크
self.addEventListener('push', (e) => {
  const d = e.data.json();
  e.waitUntil(self.registration.showNotification(d.title, { body: d.body, data: d.url }));
});
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  e.waitUntil(clients.openWindow(e.notification.data));  // 정확한 화면으로(딥링크)
});
